<script setup>
import { computed } from 'vue'
import { RouterLink } from 'vue-router'
import { products, formatIDR } from '../data/products'
import { useCartStore } from '../stores/cart'
const cart=useCartStore()
const items=computed(()=>cart.items.map((item,index)=>({...item,index,product:products.find(p=>p.id===item.productId)})).filter(i=>i.product))
function waOrder(){const text=items.value.map(i=>`${i.qty}x ${i.product.name} (${i.size}, ${i.grind})`).join('\n');return `https://wa.me/?text=${encodeURIComponent(`Halo Dharma Roastery, saya ingin bertanya tentang pesanan demo:\n${text}\nTotal demo: ${formatIDR(cart.subtotal)}`)}`}
</script>
<template><div class="cart-page"><div class="breadcrumbs"><RouterLink to="/">Beranda</RouterLink><span>/</span><b>Tas kopi</b></div><div class="cart-title"><div><span class="section-index">SEBELUM DISANGRAI UNTUKMU</span><h1>Tas kopi<span>.</span></h1></div><span>{{ cart.count }} ITEM</span></div><div v-if="items.length" class="cart-layout"><div class="cart-lines"><article v-for="item in items" :key="item.index" class="cart-line"><RouterLink :to="`/product/${item.product.id}`" class="cart-line-image"><img :src="item.product.image" :alt="item.product.name"/></RouterLink><div class="cart-line-info"><div class="cart-line-top"><div><span>{{ item.product.region }} · {{ item.product.process }}</span><RouterLink :to="`/product/${item.product.id}`">{{ item.product.name }}</RouterLink><p>{{ item.size }} · {{ item.grind }}</p></div><button class="remove-button" aria-label="Hapus item" @click="cart.remove(item.index)">Hapus</button></div><div class="cart-line-bottom"><div class="qty-control"><button @click="cart.setQty(item.index,item.qty-1)" aria-label="Kurangi">−</button><span>{{ item.qty }}</span><button @click="cart.setQty(item.index,item.qty+1)" aria-label="Tambah">+</button></div><b>{{ formatIDR(item.product.sizes.find(s=>s.label===item.size).price*item.qty) }}</b></div></div></article><div class="cart-demo-note"><span>✳</span><p>Ini adalah <b>demo frontend</b>. Tidak ada pembayaran atau pengiriman sungguhan.</p></div></div><aside class="order-summary"><span class="section-index">RINGKASAN PESANAN</span><h2>Hampir sampai.</h2><div class="summary-row"><span>Subtotal</span><b>{{ formatIDR(cart.subtotal) }}</b></div><div class="summary-row"><span>Pengiriman</span><span>Dihitung nanti</span></div><div class="summary-total"><span>Total sementara</span><b>{{ formatIDR(cart.subtotal) }}</b></div><p>Ongkir dan detail pengiriman merupakan contoh.</p><RouterLink to="/checkout" class="button button-coral">Lanjut checkout <span>→</span></RouterLink><a :href="waOrder()" class="button button-outline" target="_blank" rel="noopener">Tanya via WhatsApp <span>↗</span></a><RouterLink to="/shop" class="continue-shopping">← Lanjut memilih kopi</RouterLink></aside></div><div v-else class="cart-empty"><div class="empty-illustration"><span>◌</span><i>✳</i></div><span class="section-index">BELUM ADA YANG DIPILIH</span><h2>Satu kopi bisa<br/><em>mengubah pagi.</em></h2><p>Mulai dengan menjelajahi rasa dan asal kopi pilihan kami.</p><RouterLink to="/shop" class="button button-dark">Temukan kopi <span>↗</span></RouterLink></div></div></template>
